insert into cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-exhibits-review-reads-saved-titles-s649','decision','The Exhibits Review and its builder read saved titles from COBI','The S649 conductor, #3260 (dc4ba840), on Sam''s Las Positas words: the Review tab and kb/_build_exhibits_review.py read the saved unified_title_assignment rows from COBI; a decided card leaves the queue; with the read pending or failed, card actions are off with the reason. The daily run of 23:53Z (28569a14) took the held queue from 168 to 0.',array['cer-procedures','exhibits','decision'],'proposed','S649, PR 3260; docs/reference/lanes/cer-procedures.md',null,null,'SkyOriole (S649)',date '2026-11-13'),
('d-review-builder-anon-read-s649','decision','The Review builder''s live read uses the public anon key, never the service key','The S649 conductor, #3260: kb/_build_exhibits_review.py --live reads saved titles with the public anon key the tab ships, never the service key (COBIx''s option, taken for least privilege and so tab and builder read the same rows). The lint that said the builder makes no network call now reads: one anon read, only under --live, no key, no write.',array['cer-procedures','exhibits','security','decision'],'proposed','S649, PR 3260 review; COBIx on #3260',null,null,'SkyOriole (S649)',date '2026-11-13'),
('d-contra-costa-commented-objectives-unread-s649','decision','Objectives inside an HTML comment stay unread','The S649 conductor, #3263: Contra Costa''s (and Columbia''s) course outline template carries an objectives block inside an HTML comment. It stays unread, since the college does not publish it; OBJECTIVES_BY_SYSTEM records the template.',array['program-requirements-harvest','course-outcomes','decision'],'proposed','S649, PR 3263; kb/course_outcomes',null,null,'SkyOriole (S649)',date '2026-11-13'),
('d-chaffey-objectives-only-read-next-s649','decision','Chaffey: an objectives-only read is next, not built','The S649 conductor, #3263: Chaffey''s outline reports print course objectives and no SLOs (queue.json none for SLOs). An objectives-only read fits Sam''s ask to collect objectives with SLOs; it is the harvest lane''s NEXT, not built.',array['program-requirements-harvest','course-outcomes','decision'],'proposed','S649, PR 3263; harvest lane',null,null,'SkyOriole (S649)',date '2026-11-13'),
('d-first-reconcile-all-records-compared-s649','decision','A college''s first reconcile is compared with main record by record','The S649 conductor, #3259 and #3262: a college''s first reconcile rescores every record, so every record and every page pick is compared with main and only the planned rows are kept. Cerro Coso: 65 compared, 5 kept, 3 restored, 15 page picks restored; Cosumnes River: 1 kept, 14 records and 58 picks restored. kb/_program_requirements_reconcile.py --calgetc-review --restore does it.',array['program-requirements-harvest','rule-10','decision'],'proposed','S649, PRs 3259 and 3262',null,null,'SkyOriole (S649)',date '2026-11-13'),
('d-cerro-coso-calgetc-35-applied-s649','decision','Cerro Coso''s transfer degrees take its printed Cal-GETC 35, applied','The S649 conductor, #3259 (bab40263): Cerro Coso''s catalog prints Cal-GETC (35 Units), PDF p.65. Reread 43521333437 replaced five rows (30766, 31540, 38665, 40868, 43206; before-values in its receipt); 40922, 41968, 44885 untouched. 31540, 38665, 43206 now pass; none of 27 passing lose ground. Display build 98e783806131, applied record b9f9af4d.',array['program-requirements-harvest','cal-getc','decision'],'proposed','S649, PR 3259; reread receipt 43521333437',null,null,'SkyOriole (S649)',date '2026-11-14'),
('d-cosumnes-39656-calgetc-34-applied-s649','decision','Cosumnes River 39656 takes the statewide Cal-GETC 34, applied','The S649 conductor, #3262 (32bd5742): Cosumnes River''s catalog pp.95-96 print a minimum per Cal-GETC area and no total, so the statewide 34 stands. Reread 43523284838 posted 39656 alone (before: ge_units empty, extracted_run 39047009824). 30566 and 33072 keep main''s records (wrong pages in the fresh capture). Display build 6e5081a4b3a0, dispatched 01:07Z.',array['program-requirements-harvest','cal-getc','decision'],'proposed','S649, PR 3262; reread receipt 43523284838',null,null,'SkyOriole (S649)',date '2026-11-14'),
('d-data-collection-links-open-in-panel-s649','decision','College Data Collection: every link opens in the side panel','The S649 conductor, #3261 (58d46cc4), on Sam''s ask 2: every link on College Data Collection opens its content in the side panel at an address of its own; the panel''s one link out is Open in a new tab. This reverses #3257''s new-tab links. The capture''s GitHub folder link gave way to What the capture holds.',array['commons','college-data-collection','decision'],'proposed','S649, PR 3261; sam-data-collection-six-asks-2026-11-13',null,null,'SkyOriole (S649)',date '2026-11-14'),
('d-data-collection-one-base-per-card-s649','decision','College Data Collection: one base per card','The S649 conductor, #3261 review round 2: where the live gap census holds a college, the card''s Passing now and Still to pass, the list''s columns and the statewide card read it (5,751 still to pass), so the causes sum to the figure; the capture''s own figures carry the label the capture. Follows d-data-collection-two-bases-s648.',array['commons','college-data-collection','decision'],'proposed','S649, PR 3261 review',null,null,'SkyOriole (S649)',date '2026-11-14'),
('d-objectives-reread-order-s649','decision','The objectives reread order: rccd, sdccd, sac, laspositas, Coastline, Golden West','The S649 conductor, #3263 plan (kb/course_outcomes/objectives_reread_plan.json): the ten colleges read before S584 are read again for objectives in the order rccd, sdccd, sac, laspositas, Coastline, Golden West, one host at a time, runner minutes only, no model call; an objectives load never replaces an SLO row. De Anza and College of Marin held.',array['program-requirements-harvest','course-outcomes','decision'],'proposed','S649, PR 3263; draft PR 3265',null,null,'SkyOriole (S649)',date '2026-11-13'),
('p-test-reads-live-review-file-s649','pitfall','A test asserting a non-empty live queue fails when the queue is worked','S649: tests/exhibits_related_actions.test.js asserted cards in the live kb/exhibits_review.json; main went red at 00:02Z 2026-11-14 when Sam''s saves emptied the queue (the second time, after S643). #3269 pinned it to tests/fixtures/exhibits_review_measured_cards.json. A test pins a measured fixture, never a live file''s size.',array['testing','exhibits','pitfall'],'proposed','S649, PR 3269',null,null,'SkyOriole (S649)',date '2026-11-14'),
('p-reviewer-copies-repo-s649','pitfall','Reviewer agents copied the repository into the scratchpad','S649: reviewer agents copied the repository into the scratchpad twice (4.7 GB each) despite the brief. A reviewer brief names a READ-ONLY worktree to serve from, and the conductor checks du on the scratchpad during each review (docs/reference/conductor_mode.md, S649).',array['conductor','governance-team-enablement','pitfall'],'proposed','S649; docs/reference/conductor_mode.md',null,null,'SkyOriole (S649)',date '2026-11-13'),
('sam-review-loop-las-positas-2026-11-13','decision','Sam: the Review loop brought back the Las Positas titles he saved','Sam, relayed by COBIx on #3223 (comment 6865613134, 1:38 PM PT 2026-11-13), verbatim: "I changed those las positas exhibits in the exhibit commons and think we have a loop going where the reanalysis does know I just relied on them and then brings them back endlessly". Built in #3260: a saved title leaves the Review queue.',array['cer-procedures','exhibits','decision'],'verified','Sam, relayed by COBIx on #3223 (comment 6865613134)','Sam Lee',now(),'SkyOriole (S649)',date '2026-11-13'),
('sam-data-collection-six-asks-2026-11-13','decision','Sam: six asks on College Data Collection','Sam, in session S649 about 22:28Z 2026-11-13, with a screenshot of Skyline''s row, verbatim first: "on college data collection: 1. use the full width of the window and add an slo/objective progress bar to the top row". Then: links open in the sidebar with a new-tab option; a CPL Pathways link; SLO and PLO links; colleges with SLOs; objectives collected with SLOs. Full words: vault braindump.',array['commons','college-data-collection','decision'],'verified','Sam, in session S649 (chat with screenshot); vault braindump 2026-11-13','Sam Lee',now(),'SkyOriole (S649)',date '2026-11-13')
on conflict (slug) do nothing;
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
select id, 'SkyOriole (S649)', 'create', 'checkpoint auto-write (S649, 2026-11-14)', to_jsonb(m)
from public.cpl_memory m where m.slug in
  ('d-exhibits-review-reads-saved-titles-s649','d-review-builder-anon-read-s649','d-contra-costa-commented-objectives-unread-s649','d-chaffey-objectives-only-read-next-s649','d-first-reconcile-all-records-compared-s649','d-cerro-coso-calgetc-35-applied-s649','d-cosumnes-39656-calgetc-34-applied-s649','d-data-collection-links-open-in-panel-s649','d-data-collection-one-base-per-card-s649','d-objectives-reread-order-s649','p-test-reads-live-review-file-s649','p-reviewer-copies-repo-s649','sam-review-loop-las-positas-2026-11-13','sam-data-collection-six-asks-2026-11-13')
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select m.slug, length(m.summary) as summary_chars, count(l.id) filter (where l.action = 'create') as creates
from public.cpl_memory m left join public.cpl_memory_log l on l.memory_id = m.id
where m.slug in
  ('d-exhibits-review-reads-saved-titles-s649','d-review-builder-anon-read-s649','d-contra-costa-commented-objectives-unread-s649','d-chaffey-objectives-only-read-next-s649','d-first-reconcile-all-records-compared-s649','d-cerro-coso-calgetc-35-applied-s649','d-cosumnes-39656-calgetc-34-applied-s649','d-data-collection-links-open-in-panel-s649','d-data-collection-one-base-per-card-s649','d-objectives-reread-order-s649','p-test-reads-live-review-file-s649','p-reviewer-copies-repo-s649','sam-review-loop-las-positas-2026-11-13','sam-data-collection-six-asks-2026-11-13')
group by m.slug, m.summary order by m.slug;
